package com.example.simpleaccountant.ui.customers;import android.view.*;import android.widget.*;import androidx.annotation.NonNull;import androidx.recyclerview.widget.RecyclerView;import com.example.simpleaccountant.R;import com.example.simpleaccountant.data.model.Customer;import java.util.*;
public class CustomerAdapter extends RecyclerView.Adapter<CustomerAdapter.VH>{public interface Listener{void onDelete(Customer c);}private List<Customer> items=new ArrayList<>();private final Listener l;public CustomerAdapter(Listener l){this.l=l;}public void setItems(List<Customer> x){items=x;notifyDataSetChanged();}@NonNull @Override public VH onCreateViewHolder(@NonNull ViewGroup p,int v){return new VH(LayoutInflater.from(p.getContext()).inflate(R.layout.item_simple,p,false));}@Override public void onBindViewHolder(@NonNull VH h,int i){Customer c=items.get(i);h.t1.setText(c.getFullName());h.t2.setText(c.getPhone());h.del.setOnClickListener(v->l.onDelete(c));}@Override public int getItemCount(){return items.size();}static class VH extends RecyclerView.ViewHolder{TextView t1,t2;ImageButton del;VH(View v){super(v);t1=v.findViewById(R.id.t1);t2=v.findViewById(R.id.t2);del=v.findViewById(R.id.btnDelete);}}}
